    "grammar-flashcards": {
      "title": "Lesson 14 Grammar Flashcards",
      "cards": [
        {
          "prompt": "What happens to ν before -σι?",
          "answer": "It drops: ἡγεμόσι(ν)."
        },
        {
          "prompt": "How does a labial combine with σ?",
          "answer": "π, β, or φ plus σ is written ψ."
        },
        {
          "prompt": "Which form agrees with neuter singular πρᾶγμα?",
          "answer": "σῶφρον: τὸ σῶφρον πρᾶγμα."
        },
        {
          "prompt": "Is τίς a pronoun in τίς ἄρχει;?",
          "answer": "Yes; it stands alone as the subject."
        },
        {
          "prompt": "Does τις necessarily ask a question?",
          "answer": "No. It refers to an unspecified person or thing."
        }
      ]
    },
