    "grammar-flashcards": {
      "title": "Lesson 17 Grammar Flashcards",
      "cards": [
        {
          "prompt": "ὁ Λάχης ἀκούων σκέπτεται.",
          "answer": "Laches considers while listening. — Forming Present Active Participles"
        },
        {
          "prompt": "ἡ γυνὴ λέγουσα μένει.",
          "answer": "The woman remains while speaking (supplementary example). — Forming Present Active Participles"
        },
        {
          "prompt": "ὁ Σωκράτης τὸν λέγοντα βλέπει.",
          "answer": "Socrates watches the speaker. — Declining -ων, -ουσα, -ον"
        },
        {
          "prompt": "τῶν μενόντων ἡ γνώμη καλή ἐστιν.",
          "answer": "The judgment of those remaining is good (supplementary example). — Declining -ων, -ουσα, -ον"
        },
        {
          "prompt": "οἱ ἀκούοντες τὴν ἐρώτησιν σκέπτονται.",
          "answer": "The listeners consider the question. — Finding the Person Described"
        },
        {
          "prompt": "ὁ Σωκράτης τὸν μένοντα βλέπει.",
          "answer": "Socrates sees the man remaining (supplementary example). — Finding the Person Described"
        },
        {
          "prompt": "ὁ τὴν νόσον φέρων κινδύνους ἔχει.",
          "answer": "The person bearing illness faces dangers. — Describing, Naming, and Adding Circumstances"
        },
        {
          "prompt": "ὁ Λάχης λέγων τὸ παράδειγμα δηλοῖ.",
          "answer": "Laches explains the example while speaking (supplementary example). — Describing, Naming, and Adding Circumstances"
        },
        {
          "prompt": "οἱ Σκύθαι φεύγοντες μάχονται.",
          "answer": "The Scythians fight while fleeing. — Ongoing Action with a Main Verb"
        },
        {
          "prompt": "ὁ Σωκράτης λέγων ἐρωτᾷ.",
          "answer": "Socrates asks while speaking (supplementary example). — Ongoing Action with a Main Verb"
        }
      ]
    },
