    "grammar-flashcards": {
      "title": "Lesson 21 Grammar Flashcards",
      "cards": [
        {
          "prompt": "What marks past indicative time in ἔλαβον?",
          "answer": "the augment ἐ-. The indicative aorist has augment and secondary endings."
        },
        {
          "prompt": "In οἱ Ἕλληνες ἔλαβον, who took?",
          "answer": "the Greeks. The plural subject resolves the ambiguous -ον ending."
        },
        {
          "prompt": "Which means “we took” (active)?",
          "answer": "ἐλάβομεν. -ομεν identifies first plural active."
        },
        {
          "prompt": "What person is ἐλάβου?",
          "answer": "second singular middle. Second-aorist middle second singular ends in -ου."
        },
        {
          "prompt": "Does an aorist necessarily mean an instant?",
          "answer": "no, it views the action as a whole. Aspect describes presentation, not measured duration."
        },
        {
          "prompt": "Which presents flight as ongoing now?",
          "answer": "φεύγουσιν. The present indicative opens the action as ongoing."
        },
        {
          "prompt": "Which is feminine nominative singular active?",
          "answer": "λαβοῦσα. λαβοῦσα has feminine agreement."
        },
        {
          "prompt": "Which is genitive masculine singular active?",
          "answer": "λαβόντος. -οντος marks the active genitive singular."
        },
        {
          "prompt": "What dictionary verb supplies ἔμαθον?",
          "answer": "μανθάνω. μαθ- is the second-aorist stem of μανθάνω."
        },
        {
          "prompt": "Which is the aorist of λαμβάνω?",
          "answer": "ἔλαβον. The principal parts link λαμβάνω with ἔλαβον."
        }
      ]
    },
